from typing import List

def parse_music(music_string: str) -> List[int]:
    notes = {'o': 4, '|': 2, '.': 1}
    parsed_notes = []
    i = 0
    while i < len(music_string):
        if music_string[i] in notes:
            beat_value = notes[music_string[i]]
            if i + 1 < len(music_string) and music_string[i + 1] in notes:
                beat_value *= notes[music_string[i + 1]]
                i += 2
            else:
                i += 1
            parsed_notes.append(beat_value)
        else:
            i += 1
    return parsed_notes
